L = assign['l_count']
d = assign['step_d']
# Basic domain checks
if not isinstance(L, int) or not isinstance(d, int):
    return (False, None)
if L < 3 or d < 2:
    # Too trivial polynomial or invalid
    return (False, None)
N = L * d
if N <= 0:
    return (False, None)
if 360 % N != 0:
    # Angles would not be integer degrees; we enforce integrality
    return (False, None)
# Compute theta: angles of roots are 360 * m / N degrees for integers m with 1 <= m <= floor((N-1)/2), excluding multiples of d
half = (N - 1) // 2
K = half // d
total = half * (half + 1) // 2
excluded = d * K * (K + 1) // 2
msum = total - excluded
step_deg = 360 // N
theta = (step_deg * msum) % 360
# Enforce nontrivial difficulty (avoid easy-to-guess multiples of 90)
if theta in (0, 90, 180, 270):
    return (False, None)
return (True, theta)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

